using System;
using System.Collections;
using LittleLeo;
using LittleLeo.Variables;
using NaughtyAttributes;
using Spine;
using Spine.Unity;
using UnityEngine;

namespace Astrea;

public class SpriteControl : MonoBehaviour
{
	private Color purifyTintColor = new Color(0.37f, 0.33f, 0.66f, 1f);

	private Color corruptTintColor = new Color(0.43f, 0.13f, 0.14f, 1f);

	[Header("Blink")]
	[SerializeField]
	private FloatReference blinkCycleDurationFloatReference;

	[SerializeField]
	private IntReference cyclesIntReference;

	[Header("Purify Tint Animation")]
	[SerializeField]
	private AnimationCurveReference purifyTintCurveReference;

	[SerializeField]
	private FloatReference purifyDurationFloatReference;

	[Header("Corrupt Tint Animation")]
	[SerializeField]
	private FloatReference corruptBlinkCycleDurationFloatReference;

	[SerializeField]
	private IntReference corruptCyclesIntReference;

	[Header("Skeleton Animation")]
	[SerializeField]
	protected GameObject skeletonPrefab;

	protected bool highlighted;

	protected Transform skeletonTransform;

	protected SkeletonAnimation animationSkeleton;

	private Vector3 defaultAnimationSkeletonPosition;

	protected MeshRenderer skeletonMeshRenderer;

	protected SpriteRenderer lightSprite;

	private Vector3 defaultLightPosition;

	private Vector3 defaultLightScale;

	protected SpriteRenderer shadowSprite;

	private Vector3 defaultShadowScaling;

	protected AnimationData animationData;

	protected UnitsMiscData unitsMiscData;

	protected bool enableUnitsMiscData;

	protected Coroutine animationCoroutine;

	protected Coroutine visualEffectCoroutine;

	public MaterialPropertyBlock materialPropertyBlock;

	[Header("Mods")]
	[SerializeField]
	private bool enableModdedSpritePrefab;

	[SerializeField]
	[HideIf("enableModdedSpritePrefab")]
	private GameObject moddedSpritePrefab;

	protected SpriteRenderer moddedSpriteRenderer;

	public Transform SkeletonTransform => skeletonTransform;

	public Transform AnimationSkeletonTransform => animationSkeleton.transform;

	protected virtual void Awake()
	{
		materialPropertyBlock = new MaterialPropertyBlock();
	}

	protected virtual void SpawnSkeletonAnimation()
	{
		if (animationSkeleton == null)
		{
			skeletonTransform = UnityEngine.Object.Instantiate(skeletonPrefab).transform;
			animationSkeleton = skeletonTransform.GetComponentInChildren<SkeletonAnimation>();
			skeletonMeshRenderer = animationSkeleton.GetComponent<MeshRenderer>();
			shadowSprite = skeletonTransform.GetChild(1).GetComponent<SpriteRenderer>();
			lightSprite = skeletonTransform.GetChild(2).GetComponent<SpriteRenderer>();
			defaultLightPosition = lightSprite.transform.localPosition;
			defaultLightScale = lightSprite.transform.localScale;
			defaultAnimationSkeletonPosition = animationSkeleton.transform.localPosition;
			defaultShadowScaling = shadowSprite.transform.localScale;
		}
		skeletonTransform.localScale = Vector3.one * 0.25f;
		if (!animationData.Modded)
		{
			animationSkeleton.skeletonDataAsset = animationData.SkeletonDataAsset;
			animationSkeleton.ClearState();
			animationSkeleton.Initialize(overwrite: true);
		}
		else
		{
			CheckSpawnModdedSpriteRendererPrefab();
		}
		animationSkeleton.gameObject.SetActive(!animationData.Modded);
		if (moddedSpriteRenderer != null)
		{
			moddedSpriteRenderer.gameObject.SetActive(animationData.Modded);
		}
		InitializeMaterialProperties();
		CheckUnitsMiscData();
		if (animationData.HasAnimation(AnimationType.Starting))
		{
			PlayAnimationForced(AnimationType.Starting, AnimationChangeType.StayInTheNewAnimationLooping);
		}
		else
		{
			PlayAnimationForced(AnimationType.Idle, AnimationChangeType.StayInTheNewAnimationLooping);
		}
		CheckShadow();
		CheckLight();
	}

	private void CheckSpawnModdedSpriteRendererPrefab()
	{
		if (moddedSpriteRenderer == null)
		{
			moddedSpriteRenderer = UnityEngine.Object.Instantiate(moddedSpritePrefab, skeletonTransform).GetComponent<SpriteRenderer>();
		}
	}

	protected virtual void InitializeMaterialProperties()
	{
		SetMaterialColor(Color.white);
		SetMaterialInt("_MultiplyColor", 1);
	}

	private void CheckUnitsMiscData()
	{
		if (enableUnitsMiscData)
		{
			if (unitsMiscData.EnableCustomSpinePosition)
			{
				animationSkeleton.transform.localPosition = unitsMiscData.CustomSpineGameObjectPosition;
			}
			else
			{
				animationSkeleton.transform.localPosition = defaultAnimationSkeletonPosition;
			}
			if (unitsMiscData.EnableCustomSpineScaling)
			{
				animationSkeleton.transform.localScale = unitsMiscData.CustomSpineGameObjectScaling;
			}
			else
			{
				animationSkeleton.transform.localScale = Vector3.one;
			}
		}
		else
		{
			animationSkeleton.transform.localPosition = defaultAnimationSkeletonPosition;
			animationSkeleton.transform.localScale = Vector3.one;
		}
	}

	private void CheckShadow()
	{
		if (enableUnitsMiscData)
		{
			shadowSprite.gameObject.SetActive(!unitsMiscData.DisableShadowSprite);
			shadowSprite.transform.localScale = (unitsMiscData.EnableCustomShadowScaling ? unitsMiscData.CustomShadowScaling : defaultShadowScaling);
		}
		else
		{
			shadowSprite.gameObject.SetActive(value: true);
			shadowSprite.transform.localScale = defaultShadowScaling;
		}
		shadowSprite.SetAlpha(1f);
	}

	private void CheckLight()
	{
		if (enableUnitsMiscData)
		{
			lightSprite.SetAlpha((!unitsMiscData.DisableLight) ? 1 : 0);
			if (!unitsMiscData.DisableLight)
			{
				if (unitsMiscData.EnableCustomLightPosition)
				{
					lightSprite.transform.localPosition = unitsMiscData.CustomLightLightPosition;
				}
				else
				{
					lightSprite.transform.localPosition = defaultLightPosition;
				}
				if (unitsMiscData.EnableCustomLightScale)
				{
					lightSprite.transform.localScale = unitsMiscData.CustomLightScale;
				}
				else
				{
					lightSprite.transform.localScale = defaultLightScale;
				}
			}
		}
		else
		{
			lightSprite.SetAlpha(1f);
			lightSprite.transform.localPosition = defaultLightPosition;
			lightSprite.transform.localScale = defaultLightScale;
		}
	}

	public void PlayAnimation(AnimationType animationType, AnimationChangeType animationChangeType = AnimationChangeType.ReturnToPrevious, Action callback = null)
	{
		if (animationCoroutine == null && HasAnimation(animationType))
		{
			animationCoroutine = StartCoroutine(InnerPlayAnimation(animationType, animationChangeType, callback));
		}
	}

	protected IEnumerator PlayAnimationCoroutine(AnimationType animationType, AnimationChangeType animationChangeType = AnimationChangeType.ReturnToPrevious, Action callback = null)
	{
		if (HasAnimation(animationType) && animationCoroutine == null)
		{
			animationCoroutine = StartCoroutine(InnerPlayAnimation(animationType, animationChangeType, callback));
			yield return animationCoroutine;
		}
	}

	public void PlayAnimationIfSpecificAnimationIsNotPlaying(AnimationType animationType, AnimationType animationTypeToCheck, AnimationChangeType animationChangeType = AnimationChangeType.ReturnToPrevious, Action callback = null)
	{
		if (!IsAnimationPlaying(animationTypeToCheck))
		{
			PlayAnimation(animationType, animationChangeType, callback);
		}
	}

	public bool IsAnimationPlaying(AnimationType animationTypeToCheck)
	{
		return animationTypeToCheck.ToString() == animationSkeleton.AnimationName;
	}

	public void PlayAnimationForcedIfSpecificAnimationIsNotPlaying(AnimationType animationType, AnimationType animationTypeToCheck, AnimationChangeType animationChangeType = AnimationChangeType.ReturnToPrevious, Action callback = null)
	{
		if (!IsAnimationPlaying(animationTypeToCheck))
		{
			PlayAnimationForced(animationType, animationChangeType, callback);
		}
	}

	public void PlayAnimationForcedIfSpecificAnimationIsNotPlaying(AnimationType animationType, AnimationType[] animationTypeToChecks, AnimationChangeType animationChangeType = AnimationChangeType.ReturnToPrevious, Action callback = null)
	{
		for (int i = 0; i < animationTypeToChecks.Length; i++)
		{
			if (IsAnimationPlaying(animationTypeToChecks[i]))
			{
				return;
			}
		}
		PlayAnimationForced(animationType, animationChangeType, callback);
	}

	public void PlayAnimationForced(AnimationType animationType, AnimationChangeType animationChangeType = AnimationChangeType.ReturnToPrevious, Action callback = null)
	{
		if (HasAnimation(animationType))
		{
			if (animationCoroutine != null)
			{
				StopCoroutine(animationCoroutine);
			}
			animationCoroutine = ReferenceSingleton<CoroutineHandler>.Instance.StartCoroutine(InnerPlayAnimation(animationType, animationChangeType, callback));
		}
	}

	public IEnumerator PlayAnimationForcedCoroutine(AnimationType animationType, AnimationChangeType animationChangeType = AnimationChangeType.ReturnToPrevious, Action callback = null)
	{
		if (HasAnimation(animationType))
		{
			if (animationCoroutine != null)
			{
				StopCoroutine(animationCoroutine);
			}
			animationCoroutine = StartCoroutine(InnerPlayAnimation(animationType, animationChangeType, callback));
			yield return animationCoroutine;
		}
	}

	public void PlayAnimationForcedCoroutine(MonoBehaviour mono, AnimationType animationType, AnimationChangeType animationChangeType = AnimationChangeType.ReturnToPrevious, Action callback = null)
	{
		if (HasAnimation(animationType))
		{
			if (animationCoroutine != null)
			{
				StopCoroutine(animationCoroutine);
			}
			animationCoroutine = mono.StartCoroutine(InnerPlayAnimation(animationType, animationChangeType, callback));
		}
	}

	public bool HasAnimation(AnimationType animationType)
	{
		return animationData.HasAnimation(animationType);
	}

	public float GetAnimationDuration(AnimationType animationType)
	{
		return animationData.GetAnimationDuration(animationType);
	}

	protected IEnumerator InnerPlayAnimation(AnimationType animationType, AnimationChangeType animationChangeType, Action callback = null)
	{
		if (animationData.Modded)
		{
			moddedSpriteRenderer.sprite = animationData.GetModdedSpriteByType(animationType);
			moddedSpriteRenderer.material.SetTexture("_MainTex", moddedSpriteRenderer.sprite.texture);
		}
		else
		{
			switch (animationChangeType)
			{
			case AnimationChangeType.ReturnToPrevious:
			{
				string previousAnimation = animationSkeleton.AnimationName;
				TrackEntry trackEntry = animationSkeleton.state.SetAnimation(0, animationData.GetAnimationByType(animationType), loop: false);
				yield return new WaitForSpineAnimationComplete(trackEntry);
				animationSkeleton.state.SetAnimation(0, previousAnimation, loop: true);
				break;
			}
			case AnimationChangeType.ReturnToIdleAnimation:
			{
				TrackEntry trackEntry = animationSkeleton.state.SetAnimation(0, animationData.GetAnimationByType(animationType), loop: false);
				yield return new WaitForSpineAnimationComplete(trackEntry);
				animationSkeleton.state.SetAnimation(0, animationData.GetAnimationByType(AnimationType.Idle), loop: true);
				break;
			}
			case AnimationChangeType.StayInTheNewAnimationNotLooping:
			case AnimationChangeType.StayInTheNewAnimationLooping:
			{
				bool loop = animationChangeType == AnimationChangeType.StayInTheNewAnimationLooping;
				TrackEntry trackEntry = animationSkeleton.state.SetAnimation(0, animationData.GetAnimationByType(animationType), loop);
				yield return new WaitForSpineAnimationComplete(trackEntry);
				break;
			}
			}
		}
		animationCoroutine = null;
		callback?.Invoke();
	}

	public TrackEntry GetCurrentTrackEntry()
	{
		return animationSkeleton.state.GetCurrent(0);
	}

	public void SetMixDuration(float mixDuration)
	{
		if (!animationData.Modded)
		{
			GetCurrentTrackEntry().MixDuration = mixDuration;
		}
	}

	public void PlayVisualEffect(VisualEffectType effectType)
	{
		if (visualEffectCoroutine == null)
		{
			ReferenceSingleton<CoroutineHandler>.Instance.StartCoroutine(InnerPlayVisualEffect(effectType));
		}
	}

	private IEnumerator InnerPlayVisualEffect(VisualEffectType effectType)
	{
		switch (effectType)
		{
		case VisualEffectType.Blink:
			yield return visualEffectCoroutine = ReferenceSingleton<CoroutineHandler>.Instance.StartCoroutine(BlinkRenderer());
			break;
		case VisualEffectType.Purify:
			SetMaterialInt("_MultiplyColor", 1);
			yield return visualEffectCoroutine = ReferenceSingleton<CoroutineHandler>.Instance.StartCoroutine(BlinkRendererColor());
			break;
		case VisualEffectType.Corrupt:
			SetMaterialInt("_MultiplyColor", 1);
			yield return visualEffectCoroutine = ReferenceSingleton<CoroutineHandler>.Instance.StartCoroutine(BlinkRendererColor());
			break;
		}
		visualEffectCoroutine = null;
	}

	public void OnClick()
	{
		ResetOutlineBrightness();
	}

	public void OnBlink()
	{
		InvokeAlternatives.InvokeAfterMultipleFrames(ReferenceSingleton<CoroutineHandler>.Instance, 7, delegate
		{
			PlayVisualEffect(VisualEffectType.Blink);
		});
	}

	public virtual void OnReceivePurify()
	{
		PlayVisualEffect(VisualEffectType.Purify);
	}

	public virtual void OnReceiveCorruption()
	{
		PlayVisualEffect(VisualEffectType.Corrupt);
	}

	public virtual void OnReceiveFatalDamage()
	{
	}

	public virtual void OnMouseOver()
	{
		if (!highlighted)
		{
			SetMaterialFloat("_HighlightTexAlpha", 1f);
			SetMaterialFloat("_GrayScaleBlend", 1f);
			highlighted = true;
		}
	}

	public virtual void OnMouseExit()
	{
		ResetOutlineBrightness();
	}

	protected virtual void ResetOutlineBrightness()
	{
		highlighted = false;
		SetMaterialFloat("_HighlightTexAlpha", 0f);
		SetMaterialFloat("_GrayScaleBlend", 0f);
	}

	private void SetMaterialInt(string property, int value)
	{
		if (animationData.Modded)
		{
			moddedSpriteRenderer.SetRendererInt(materialPropertyBlock, property, value);
		}
		else
		{
			skeletonMeshRenderer.SetRendererInt(materialPropertyBlock, property, value);
		}
	}

	private void SetMaterialFloat(string property, float value)
	{
		if (animationData.Modded)
		{
			moddedSpriteRenderer.SetRendererFloat(materialPropertyBlock, property, value);
		}
		else
		{
			skeletonMeshRenderer.SetRendererFloat(materialPropertyBlock, property, value);
		}
	}

	private void SetMaterialColor(Color color)
	{
		if (animationData.Modded)
		{
			moddedSpriteRenderer.SetRendererColor(materialPropertyBlock, color);
		}
		else
		{
			skeletonMeshRenderer.SetRendererColor(materialPropertyBlock, color);
		}
	}

	private IEnumerator BlinkRenderer()
	{
		if (animationData.Modded)
		{
			return moddedSpriteRenderer.BlinkRenderer(materialPropertyBlock, 1f, 0f, blinkCycleDurationFloatReference.Value, cyclesIntReference.Value);
		}
		return skeletonMeshRenderer.BlinkRenderer(materialPropertyBlock, 1f, 0f, blinkCycleDurationFloatReference.Value, cyclesIntReference.Value);
	}

	private IEnumerator BlinkRendererColor()
	{
		if (animationData.Modded)
		{
			return moddedSpriteRenderer.BlinkRendererColor(materialPropertyBlock, Color.white, corruptTintColor, corruptBlinkCycleDurationFloatReference.Value, corruptCyclesIntReference.Value);
		}
		return skeletonMeshRenderer.BlinkRendererColor(materialPropertyBlock, Color.white, corruptTintColor, corruptBlinkCycleDurationFloatReference.Value, corruptCyclesIntReference.Value);
	}
}
